	"application/view/DialogEmailPedido.fragment.xml":'<core:FragmentDefinition xmlns="sap.m" xmlns:core="sap.ui.core" xmlns:mvc="sap.ui.core.mvc" xmlns:f="sap.ui.layout.form" xmlns:l="sap.ui.layout" id="idPageAlterar" width="50%" height="50%"><Dialog id="idDialogEmail" title="Envio espelho do pedido por E-mail" initialFocus="idEmail" icon="sap-icon://email" stretch="true" class="customizedDialog" busyIndicatorDelay="0"><content><f:Form id="idForm" editable="true" ><f:layout><f:ResponsiveGridLayout labelSpanXL="2" labelSpanL="2" labelSpanM="2" labelSpanS="3" adjustLabelSpan="false" emptySpanXL="0" emptySpanL="0" emptySpanM="0" emptySpanS="0" columnsXL="4" columnsL="4" columnsM="8"/></f:layout><f:FormContainer ><f:formElements><f:FormElement label="Representante"><f:fields><Input id="idCodRepres" type="Text" value="{modelParamDialog>/CodRepres} - {modelParamDialog>/NomeRepres}" blocked="true"><layoutData><l:GridData span="XL8 L8 M8 S12" linebreakXL="false" linebreakS="true"/></layoutData></Input></f:fields></f:FormElement><f:FormElement label="E-mail"><f:fields><Input id="idEmail" type="Text" value="{modelParamDialog>/EmailPedido}"><layoutData><l:GridData span="XL8 L8 M8 S12" linebreakXL="false" linebreakS="true"/></layoutData></Input></f:fields></f:FormElement></f:formElements></f:FormContainer></f:Form></content><buttons><Button id="idBtEnvioDanfe" text="Enviar" icon="sap-icon://accept" press="onEnviarEmailPedido" type="Accept"/><Button text="Sair" icon="sap-icon://undo" press="onDialogClose"/></buttons></Dialog></core:FragmentDefinition>',
